import { useState } from "react";
import { z } from "zod";
import { SectionPage, Specimen } from "../kit.js";
import { Form, FormStack, formBehaviour, useAppForm } from "../../ui/form/index.js";
import { otpSchema, type OtpStatus } from "../../ui/otp-field/index.js";
import { wait } from "../sections/forms.fixtures.js";

/** The code the demo accepts. */
const GOOD = "482913";

function VerifyDemo() {
  const [status, setStatus] = useState<OtpStatus | undefined>();
  const form = useAppForm({
    ...formBehaviour,
    defaultValues: { code: "" },
    validators: { onDynamic: z.object({ code: otpSchema() }) },
    onSubmit: async ({ value }) => {
      await wait(500);
      if (value.code !== GOOD) {
        setStatus("error");
        throw new Error("That code is not right");
      }
      setStatus("success");
    },
  });
  return (
    <Form form={form} aria-label="Verify" className="w-full" data-testid="otp-form">
      <FormStack>
        <form.AppField name="code" listeners={{ onChange: () => setStatus(undefined) }}>
          {(field) => (
            <field.OtpField
              label="Verification code"
              hint={
                status === "error"
                  ? "That code is not right. Check the app and try again."
                  : `Enter the code from your authenticator (try ${GOOD}).`
              }
              autoSubmit
              status={status}
            />
          )}
        </form.AppField>
        <div>
          <form.SubmitButton>Verify</form.SubmitButton>
        </div>
      </FormStack>
    </Form>
  );
}

export default function OtpFieldSection() {
  const [code, setCode] = useState("");
  return (
    <SectionPage>
      <Specimen
        title="Submit on complete"
        description="With autoSubmit the last digit submits the form; the boxes show the outcome in place."
      >
        <VerifyDemo />
      </Specimen>
    </SectionPage>
  );
}
